-- Removes the sample recipes and suppliers, and any sample ingredient no real recipe uses.
-- Generated by seed/sample-recipes.mjs. Sample dishes added to a retreat menu are taken off it too.
DELETE FROM meal_dish_alternatives WHERE meal_dish_id IN (SELECT id FROM meal_dishes WHERE recipe_id IN (SELECT id FROM recipes WHERE title IN ('Full English breakfast (sample)', 'Shakshuka with feta and flatbreads (sample)', 'Overnight oats with berries (sample)', 'Hummus with crudités (sample)', 'Flapjacks (sample)', 'Banana and walnut bread (sample)', 'Beef and ale stew with mash (sample)', 'Chicken tikka masala with rice (sample)', 'Baked salmon with new potatoes and green beans (sample)', 'Big green salad (sample)')));
DELETE FROM meal_dishes WHERE recipe_id IN (SELECT id FROM recipes WHERE title IN ('Full English breakfast (sample)', 'Shakshuka with feta and flatbreads (sample)', 'Overnight oats with berries (sample)', 'Hummus with crudités (sample)', 'Flapjacks (sample)', 'Banana and walnut bread (sample)', 'Beef and ale stew with mash (sample)', 'Chicken tikka masala with rice (sample)', 'Baked salmon with new potatoes and green beans (sample)', 'Big green salad (sample)'));
DELETE FROM recipes WHERE title IN ('Full English breakfast (sample)', 'Shakshuka with feta and flatbreads (sample)', 'Overnight oats with berries (sample)', 'Hummus with crudités (sample)', 'Flapjacks (sample)', 'Banana and walnut bread (sample)', 'Beef and ale stew with mash (sample)', 'Chicken tikka masala with rice (sample)', 'Baked salmon with new potatoes and green beans (sample)', 'Big green salad (sample)');
DELETE FROM ingredients WHERE name IN ('Eggs', 'Smoked back bacon', 'Pork sausages', 'Vegan sausages', 'Chestnut mushrooms', 'Tomatoes', 'Baked beans', 'Sourdough bread', 'Gluten-free bread', 'Butter', 'Dairy-free spread', 'Firm tofu', 'Olive oil', 'Chopped tomatoes', 'Onions', 'Red peppers', 'Garlic cloves', 'Ground cumin', 'Smoked paprika', 'Feta', 'Flatbreads', 'Fresh coriander', 'Rolled oats', 'Gluten-free oats', 'Whole milk', 'Oat milk', 'Greek yoghurt', 'Coconut yoghurt', 'Honey', 'Maple syrup', 'Frozen mixed berries', 'Chia seeds', 'Chickpeas', 'Tahini', 'Lemons', 'Carrots', 'Cucumber', 'Golden syrup', 'Light brown sugar', 'Ripe bananas', 'Plain flour', 'Gluten-free plain flour', 'Bicarbonate of soda', 'Walnuts', 'Braising beef', 'Brown ale', 'Celery', 'Beef stock cubes', 'Vegetable stock cubes', 'Fresh thyme', 'Maris Piper potatoes', 'Portobello mushrooms', 'Green lentils', 'Tomato puree', 'Chicken thighs', 'Tikka masala paste', 'Fresh ginger', 'Double cream', 'Coconut milk', 'Cauliflower', 'Basmati rice', 'Salmon fillets', 'New potatoes', 'Green beans', 'Fresh dill', 'Mixed salad leaves', 'Cherry tomatoes', 'Red wine vinegar', 'Dijon mustard') AND id NOT IN (SELECT ingredient_id FROM recipe_ingredients);
DELETE FROM suppliers WHERE name IN ('Tesco (sample)', 'Local butcher (sample)', 'Fishmonger (sample)');
